//
// Clipboard tests: unbounded internal selection storage, and the X11 INCR
// path. The cross-process test forks so one round-trip exercises both the
// owner-side send and requestor-side receive halves of the protocol.

#include "../mkgui.c"

#include <sys/wait.h>

// Past the 1 MB per-chunk cap, with a non-aligned tail to hit the short final chunk.
#define BIG_LEN (5u * 1024u * 1024u + 12345u)

// Deterministic NUL-free payload, regenerated by index so any ordering bug shows as a mismatch at its offset.
static void clip_fill_pattern(char *buf, uint32_t len) {
	for(uint32_t i = 0; i < len; ++i) {
		buf[i] = (char)(33 + (i % 94));
	}
}

// [=]===^=[ clip_test_internal_large ]============================[=]
// Owner reading its own selection takes the internal-buffer path, no longer capped at 4 KB.
static uint32_t clip_test_internal_large(void) {
	struct mkgui_widget widgets[] = {
		MKGUI_W(MKGUI_WINDOW, 1, "clip", "", 0, 64, 64, 0, 0, 0),
	};
	struct mkgui_ctx *ctx = mkgui_ctx_create();
	struct mkgui_window *win = mkgui_window_create(ctx, NULL, widgets, 1, NULL, 0, 0);
	if(!win) {
		printf("  internal: window_create failed\n");
		mkgui_ctx_destroy(ctx);
		return 1;
	}

	char *src = (char *)malloc(BIG_LEN);
	clip_fill_pattern(src, BIG_LEN);
	mkwin_clipboard_set(win->mkwin, src, BIG_LEN);

	uint32_t got_len = 0;
	char *got = mkwin_clipboard_get(win->mkwin, &got_len);

	uint32_t ok = got && got_len == BIG_LEN && memcmp(got, src, BIG_LEN) == 0;
	if(!ok) {
		printf("  internal: mismatch (want %u, got %u)\n", BIG_LEN, got_len);
	}

	free(got);
	free(src);
	mkgui_window_destroy(win);
	mkgui_ctx_destroy(ctx);
	return ok ? 0 : 1;
}

// [=]===^=[ clip_child_requestor ]================================[=]
// Read the big selection the parent owns; exit code is the failure reason (0 == success).
static void clip_child_requestor(int ready_fd) {
	char c;
	if(read(ready_fd, &c, 1) != 1) {
		_exit(10);
	}
	close(ready_fd);

	struct mkgui_widget widgets[] = {
		MKGUI_W(MKGUI_WINDOW, 1, "clip-recv", "", 0, 64, 64, 0, 0, 0),
	};
	struct mkgui_ctx *ctx = mkgui_ctx_create();
	struct mkgui_window *win = mkgui_window_create(ctx, NULL, widgets, 1, NULL, 0, 0);
	if(!win) {
		mkgui_ctx_destroy(ctx);
		_exit(11);
	}

	uint32_t got_len = 0;
	char *got = mkwin_clipboard_get(win->mkwin, &got_len);

	int status = 0;
	if(!got) {
		status = 12;
	} else if(got_len != BIG_LEN) {
		status = 13;
	} else {
		char *ref = (char *)malloc(BIG_LEN);
		clip_fill_pattern(ref, BIG_LEN);
		if(memcmp(got, ref, BIG_LEN) != 0) {
			status = 14;
		}
		free(ref);
	}

	free(got);
	mkgui_window_destroy(win);
	mkgui_ctx_destroy(ctx);
	_exit(status);
}

// [=]===^=[ clip_test_incr_roundtrip ]============================[=]
static uint32_t clip_test_incr_roundtrip(void) {
	int ready[2];
	if(pipe(ready) != 0) {
		printf("  incr: pipe failed\n");
		return 1;
	}

	pid_t pid = fork();
	if(pid < 0) {
		printf("  incr: fork failed\n");
		close(ready[0]);
		close(ready[1]);
		return 1;
	}

	if(pid == 0) {
		close(ready[1]);
		clip_child_requestor(ready[0]);
		_exit(99);	// unreachable
	}

	close(ready[0]);

	struct mkgui_widget widgets[] = {
		MKGUI_W(MKGUI_WINDOW, 1, "clip-own", "", 0, 64, 64, 0, 0, 0),
	};
	struct mkgui_ctx *ctx = mkgui_ctx_create();
	struct mkgui_window *win = mkgui_window_create(ctx, NULL, widgets, 1, NULL, 0, 0);
	if(!win) {
		printf("  incr: parent window_create failed\n");
		close(ready[1]);
		waitpid(pid, NULL, 0);
		mkgui_ctx_destroy(ctx);
		return 1;
	}

	char *src = (char *)malloc(BIG_LEN);
	clip_fill_pattern(src, BIG_LEN);
	mkwin_clipboard_set(win->mkwin, src, BIG_LEN);
	free(src);
	// XSync so the ownership is visible to the child's server-side query; XFlush only queues locally.
	XSync(win->mkwin->dpy, False);

	char go = 1;
	if(write(ready[1], &go, 1) != 1) {
		printf("  incr: ready signal failed\n");
	}
	close(ready[1]);

	// Pump the owner loop to service the requestor's SelectionRequest; deadline keeps a stall from hanging CI.
	uint64_t deadline = mkgui_now_ns() + 60ull * 1000000000ull;
	int status = 0;
	uint32_t timed_out = 0;
	for(;;) {
		if(waitpid(pid, &status, WNOHANG) == pid) {
			break;
		}
		if(mkgui_now_ns() > deadline) {
			timed_out = 1;
			kill(pid, SIGKILL);
			waitpid(pid, &status, 0);
			break;
		}
		mkwin_wait(win->mkwin, 20ll * 1000000ll);
		struct mkgui_event ev;
		while(mkgui_window_poll(win, &ev)) {
		}
	}

	uint32_t ok = !timed_out && WIFEXITED(status) && WEXITSTATUS(status) == 0;
	if(timed_out) {
		printf("  incr: timed out waiting for child\n");
	} else if(!ok) {
		printf("  incr: child failed (exit %d)\n", WIFEXITED(status) ? WEXITSTATUS(status) : -1);
	}

	mkgui_window_destroy(win);
	mkgui_ctx_destroy(ctx);
	return ok ? 0 : 1;
}

// [=]===^=[ main ]================================================[=]
int main(void) {
	Display *probe = XOpenDisplay(NULL);
	if(!probe) {
		fprintf(stderr, "test_clipboard: FAIL: no X display\n");
		return 1;

	}
	XCloseDisplay(probe);

	uint32_t failed = 0;
	failed |= clip_test_internal_large();
	failed |= clip_test_incr_roundtrip();

	if(failed) {
		printf("test_clipboard: FAIL\n");
		return 1;
	}
	printf("test_clipboard: all tests passed\n");
	return 0;
}
